import {esc,fmt} from '../../ui/format.js';
import {METRICS} from '../../core/statistics.js';
import {describe,difference} from '../../core/inference.js';
export function scenariosView({m,result,baseline}){
 const interval=s=>s?.confidence?.lower==null?'CI unavailable':`[${fmt(s.confidence.lower,4)}, ${fmt(s.confidence.upper,4)}]`;
 const comparable=baseline&&result&&baseline.result.window?.horizonSeconds===result.window?.horizonSeconds&&baseline.result.window?.warmupSeconds===result.window?.warmupSeconds;
 const paired=comparable&&result.seeds&&JSON.stringify(result.seeds)===JSON.stringify(baseline.result.seeds);
 return `<h1>Scenarii & baseline</h1><div class="panel"><p>Same seed does not guarantee identical random pairs between different models. Optional CRN separates duration, quality, routing, failure and repair streams using stable operation/resource IDs. Changed IDs, scheduling or draw counts can reduce or reverse variance reduction. No automatic recommendation is made.</p><div class="row"><button data-action="baseline" ${result?'':'disabled'}>Fixeaza baseline</button><button data-action="restore" ${baseline?'':'disabled'}>Restaureaza baseline</button><button data-action="comparison" ${baseline?'':'disabled'}>Export comparatie</button></div>${baseline?`<p>${paired?'Difference CI: paired replication differences for matching seeds; this does not claim event-level pairing.':'Difference CI: Welch independent-sample approximation; shared randomness can invalidate independence.'}</p>${!comparable?'<div class="notice">Observation windows differ or are unknown: do not interpret this as an isolated design effect.</div>':''}<table><thead><tr><th>KPI</th><th>Baseline mean / CI</th><th>Current mean / CI</th><th>Difference / CI</th></tr></thead><tbody>${Object.entries(METRICS).map(([k,[label,unit]])=>{const a=baseline.result.summary?.[k],b=result?.summary?.[k];let d=difference(a,b,result?.confidence??.95);if(paired){const s=describe(result.runs.map((r,i)=>Number.isFinite(r[k])&&Number.isFinite(baseline.result.runs[i][k])?r[k]-baseline.result.runs[i][k]:null),result.confidence);d={mean:s.mean,lower:s.confidence.lower,upper:s.confidence.upper};}return `<tr><td>${esc(k==='wip'?'WIP mediu':label)} (${unit})</td><td>${fmt(a?.mean,4)} ${interval(a)}</td><td>${fmt(b?.mean,4)} ${interval(b)}</td><td>${fmt(d.mean,4)} ${d.lower==null?'CI unavailable':`[${fmt(d.lower,4)}, ${fmt(d.upper,4)}]`}</td></tr>`;}).join('')}</tbody></table><p>Every scalar KPI uses all available replications; missing/undefined values are excluded. Save or export experiments to retain results; the comparison baseline itself remains session-local.</p>`:'<p>Run a model to establish the first baseline.</p>'}</div>`;
}
